// Independent real-play/lifecycle challenge; chosen release report remains unchanged.
import fs from 'node:fs';
import crypto from 'node:crypto';
import {chromium} from '/validator/node_modules/playwright/index.mjs';
import {tapReachable} from '/validator/touch_scroll_probe.mjs';
const hash=v=>crypto.createHash('sha256').update(v).digest('hex'),html=fs.readFileSync('/input/game.html','utf8'),config=JSON.parse(fs.readFileSync('/input/config.json','utf8'));
const checks=[],snapshots=[],evidence=[];const record=(name,passed,detail)=>checks.push({name,passed,detail});const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage','--disable-background-networking']});
for(const width of [1280,390]){
 const touch=width===390,context=await browser.newContext({viewport:{width,height:touch?844:800},isMobile:touch,hasTouch:touch,serviceWorkers:'block'});await context.tracing.start({screenshots:true,snapshots:true});const page=await context.newPage();page.setDefaultTimeout(9000);const errors=[],network=[];page.on('pageerror',e=>errors.push(e.message));let initial=true;
 await context.route('**/*',route=>{if(initial&&route.request().url()==='http://review.invalid/'){initial=false;return route.fulfill({contentType:'text/html',body:html});}network.push(route.request().url());return route.abort();});
 const click=selector=>touch?tapReachable(page,selector):page.locator(selector).click();const get=async name=>{const state=await page.evaluate(()=>window.__GAME_TEST__.snapshot());snapshots.push({name:name+':'+width,state});return state;};const jump=()=>touch?tapReachable(page,'[data-testid="jump"]'):page.keyboard.press('Space');
 try{
  await page.goto('http://review.invalid/');await click('[data-testid="start"]');let before=await get('pre-jump');await jump();await page.waitForTimeout(80);let after=await get('jump');record('real-jump-position:'+width,after.player.bottomY<before.player.bottomY&&after.player.vy<0&&after.phase==='playing',{real_input:touch?'raw coordinate touch':'Space',before,after});fs.writeFileSync('/evidence/jump-'+width+'.png',await page.screenshot());
  await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'));});let hidden=await get('hidden');await page.waitForTimeout(250);let waited=await get('hidden-wait');record('synthetic-hidden-time-pauses-physics:'+width,same(hidden,waited)&&hidden.paused===true,{synthetic_lifecycle:true,actual_wait_ms:250,hidden,waited});
  await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});document.dispatchEvent(new Event('visibilitychange'));});await click('[data-testid="restart"]');await page.waitForFunction(()=>window.__GAME_TEST__.snapshot().phase==='lost',{},{timeout:8000});let lost=await get('no-jump-collision');record('ordinary-no-jump-collision-loses:'+width,lost.phase==='lost'&&lost.progress<1,{real_time:true,lost});fs.writeFileSync('/evidence/lost-'+width+'.png',await page.screenshot());
  await click('[data-testid="restart"]');
  for(const obstacle of [210,370,530]){
   await page.waitForFunction(target=>{const s=window.__GAME_TEST__.snapshot();return s.phase!=='playing'||(s.player.x>=target-25&&s.player.grounded);},obstacle,{polling:8,timeout:8000});let approaching=await get('before-obstacle-'+obstacle);if(approaching.phase!=='playing')throw new Error('Game ended before legal jump '+obstacle);await jump();
  }
  await page.waitForFunction(()=>['won','lost'].includes(window.__GAME_TEST__.snapshot().phase),{},{timeout:8000});let won=await get('legal-three-jumps');record('legal-real-play-finishes:'+width,won.phase==='won'&&won.progress===1&&won.passedObstacles===3,{real_keys_or_touch:true,no_dispatch_commands:true,won});fs.writeFileSync('/evidence/won-'+width+'.png',await page.screenshot());await jump();let terminal=await get('terminal-jump');record('terminal-jump-immutable:'+width,same(won,terminal),{real_input:true});
  await click('[data-testid="restart"]');let restarted=await get('restart');record('restart-clears-terminal:'+width,restarted.phase==='playing'&&restarted.passedObstacles===0&&restarted.player.x<100,{restarted});const box=await page.locator('canvas').boundingBox();record('visible-responsive-canvas:'+width,box&&box.width>=160&&box.height>=80&&box.width<=width,{actual_canvas_box:box});
 }catch(error){record('challenge-error:'+width,false,{message:error.message});fs.writeFileSync('/evidence/error-'+width+'.png',await page.screenshot());}
 finally{record('uncaught-errors:'+width,errors.length===0,{errors});record('network:'+width,network.length===0,{network});await context.tracing.stop({path:'/evidence/trace-'+width+'.zip'});await context.close();}
}
for(const path of fs.readdirSync('/evidence').sort()){const data=fs.readFileSync('/evidence/'+path);evidence.push({path,sha256:hash(data),bytes:data.length});}
process.stdout.write(JSON.stringify({schema_version:1,scope:'Independent actual real-time keyboard and raw reachable touch jump play; synthetic visibility changes separately labelled. Chosen release reports unchanged.',passed:checks.every(c=>c.passed),html_sha256:hash(Buffer.from(html)),validator_image:config.image,review_script_sha256:hash(fs.readFileSync('/review/challenge.mjs')),browser_version:browser.version(),checks,snapshots,evidence_files:evidence}));await browser.close();

