// Independent reviewed mechanics challenge; not part of the frozen benchmark.
import fs from 'node:fs';
import crypto from 'node:crypto';
import {chromium} from '/validator/node_modules/playwright/index.mjs';
import {bridgeAdapter} from '/validator/bridge_adapter.mjs';
import {tapReachable} from '/validator/touch_scroll_probe.mjs';
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const html = fs.readFileSync('/input/game.html','utf8');
const config = JSON.parse(fs.readFileSync('/input/config.json','utf8'));
const checks = [], snapshots = [], evidence = [];
const record = (name, condition, detail) => checks.push({name,passed:condition,detail});
const same = (a,b) => JSON.stringify(a) === JSON.stringify(b);
function observe(name,snapshot){snapshots.push({name,snapshot});return snapshot;}
const browser = await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE || undefined,args:['--no-sandbox','--disable-dev-shm-usage','--disable-background-networking','--alsa-output-device=null']});
for(const width of [1280,390]){
 const touch=width===390, context=await browser.newContext({viewport:{width,height:touch?844:800},hasTouch:touch,isMobile:touch,acceptDownloads:false,serviceWorkers:'block'});
 await context.tracing.start({screenshots:true,snapshots:true,sources:false});
 const page=await context.newPage();page.setDefaultTimeout(5000);
 const errors=[],network=[];page.on('pageerror',e=>errors.push(e.message));let initial=true;
 await context.route('**/*',async route=>{if(initial && route.request().url()==='http://review.invalid/index.html' && route.request().isNavigationRequest()){initial=false;await route.fulfill({contentType:'text/html',body:html,headers:{'Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; media-src data: blob:; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"}});}else{network.push(route.request().url().slice(0,300));await route.abort();}});
 try{
  await page.goto('http://review.invalid/index.html');
  const pointer=selector=>touch?tapReachable(page,selector):page.locator(selector).click();
