const hash=v=>crypto.createHash('sha256').update(v).digest('hex'),html=fs.readFileSync('/input/game.html','utf8'),config=JSON.parse(fs.readFileSync('/input/config.json','utf8'));const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});await context.tracing.start({screenshots:true,snapshots:true});const page=await context.newPage(),observations=[],checks=[];await context.route('**/*',r=>r.request().url()==='http://review.invalid/'?r.fulfill({contentType:'text/html',body:html}):r.abort());await page.goto('http://review.invalid/');await tapReachable(page,'[data-testid="start"]');await page.evaluate(()=>window.__GAME_TEST__.setManualMode(true));
for(const n of [1,2,3]){const selector='[data-testid="target-'+n+'"]',box=await page.locator(selector).boundingBox();const point={x:box.x+box.width/2,y:box.y+box.height/2};const hit=await page.evaluate(p=>{const e=document.elementFromPoint(p.x,p.y),clip=document.querySelector('.tg-scroll').getBoundingClientRect();return{point_element:e?.tagName,point_class:e?.className,point_testid:e?.dataset?.testid,clip:{left:clip.left,right:clip.right,top:clip.top,bottom:clip.bottom}};},point);const before=await page.evaluate(()=>window.__GAME_TEST__.snapshot());await page.touchscreen.tap(point.x,point.y);const after=await page.evaluate(()=>window.__GAME_TEST__.snapshot());observations.push({target:n,box,point,hit,before,after});}
const third=observations[2];checks.push({name:'canonical-center-clipped',passed:third.point.x>third.hit.clip.right&&third.after.score===2&&third.after.phase==='playing',detail:third});fs.writeFileSync('/evidence/center-misses-390.png',await page.screenshot());const beforeScroll=await page.evaluate(()=>document.querySelector('.tg-scroll').scrollLeft);const cdp=await context.newCDPSession(page);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:340,y:450}]});for(let i=1;i<=10;i++){await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:340-250*i/10,y:450}]});await page.waitForTimeout(15);}await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForTimeout(300);const afterScroll=await page.evaluate(()=>document.querySelector('.tg-scroll').scrollLeft);checks.push({name:'ordinary-horizontal-canvas-swipe-does-not-reveal-center',passed:beforeScroll===0&&afterScroll===0,detail:{actual_touch:true,beforeScroll,afterScroll}});
const visibleEdge={x:(Math.max(third.box.x,third.hit.clip.left)+third.hit.clip.right)/2,y:third.point.y};await page.touchscreen.tap(visibleEdge.x,visibleEdge.y);const final=await page.evaluate(()=>window.__GAME_TEST__.snapshot());checks.push({name:'partially-visible-edge-can-still-hit',passed:final.phase==='won'&&final.score===3,detail:{actual_touch:true,visibleEdge,final}});fs.writeFileSync('/evidence/edge-wins-390.png',await page.screenshot());await context.tracing.stop({path:'/evidence/trace-390.zip'});const evidence=fs.readdirSync('/evidence').sort().map(path=>{const data=fs.readFileSync('/evidence/'+path);return{path,sha256:hash(data),bytes:data.length};});process.stdout.write(JSON.stringify({schema_version:1,scope:'Supplemental exact failed shooter mobile geometry diagnosis. Clock held stationary through trusted platform manual mode; all gameplay actions actual coordinate touches. No source/CSS rewrite, no release result changed. Diagnostic observations are not candidate promotion.',passed:checks.every(c=>c.passed),html_sha256:hash(Buffer.from(html)),validator_image:config.image,browser_version:browser.version(),review_script_sha256:hash(fs.readFileSync('/review/challenge.mjs')),observations,checks,evidence_files:evidence}));await browser.close();

