function createGame(ctx) {
  const names = ['Красная', 'Зелёная', 'Синяя'];
  const colors = ['red', 'green', 'blue'];
  const letters = ['R', 'G', 'B'];
  let phase = 'ready', score = 0, bestScore = 0, selectedParcelId = 0;
  let feedback = 'Нажмите «Начать», чтобы открыть почту.';
  let storageStatus = ctx.storage ? 'loading' : 'unavailable';
  let storageReason = ctx.storage ? '' : 'хранилище недоступно';
  let disposed = false, loaded = false, writing = false, persisted = -1;
  const emptyDrag = () => ({active:false, parcelId:0, pointerId:0, startX:0, startY:0, x:0, y:0, moved:false});
  let drag = emptyDrag(), offsetX = 0, offsetY = 0;
  const parcels = colors.map((color, i) => ({id:i + 1, color, delivered:false}));
  const doc = ctx.root.ownerDocument;
  const el = (tag, cls, text) => {
    const node = doc.createElement(tag);
    node.className = cls;
    if (text) node.textContent = text;
    return node;
  };
  const surface = el('section', 'post-game');
  surface.tabIndex = 0;
  surface.setAttribute('aria-label', 'Сортировщик посылок');
  const header = el('header', 'post-header');
  header.append(el('div', 'post-eyebrow', 'МАЛЕНЬКАЯ ПОЧТА • 01'), el('h1', '', 'Сортировщик посылок'), el('p', 'post-rules', 'Перетащите каждую посылку в корзину её цвета. Три доставки — победа!'));
  const stats = el('div', 'post-stats');
  const count = el('strong', 'post-count');
  const best = el('span', 'post-best');
  stats.append(count, best);
  const storage = el('p', 'post-storage');
  const rack = el('div', 'post-grid post-rack');
  const bins = el('div', 'post-grid post-bins');
  const slots = [], boxes = [], baskets = [], contents = [];
  const message = el('p', 'post-message');
  message.setAttribute('role', 'status');
  message.setAttribute('aria-live', 'polite');
  message.setAttribute('aria-atomic', 'true');
  for (let i = 0; i < 3; i++) {
    const slot = el('div', 'post-slot');
    const box = el('div', 'post-parcel ' + colors[i]);
    box.dataset.testid = 'parcel-' + (i + 1);
    box.draggable = false;
    box.setAttribute('aria-label', names[i] + ' посылка ' + (i + 1));
    box.append(el('span', 'post-stamp', String(i + 1)), el('strong', 'post-label', names[i]), el('span', 'post-small', 'ПОСЫЛКА'));
    slot.append(box);
    rack.append(slot);
    slots.push(slot); boxes.push(box);
    const basket = el('div', 'post-basket ' + colors[i]);
    basket.dataset.testid = 'basket-' + (i + 1);
    basket.append(el('strong', 'post-bin-title', (i + 1) + ' · ' + names[i]), el('span', 'post-key', 'Клавиша ' + letters[i]));
    const content = el('div', 'post-bin-content');
    basket.append(content);
    bins.append(basket); baskets.push(basket); contents.push(content);
    ctx.input.on(box, 'pointerdown', event => {
      if (event.button !== 0 || !event.isPrimary) return;
      surface.focus({preventScroll:true});
      dispatch({type:'DRAG_BEGIN', parcelId:i + 1, pointerId:event.pointerId, x:event.clientX, y:event.clientY});
      if (drag.active && drag.pointerId === event.pointerId) event.preventDefault();
    });
    ctx.input.on(box, 'pointermove', event => dispatch({type:'DRAG_MOVE', pointerId:event.pointerId, x:event.clientX, y:event.clientY}));
    ctx.input.on(box, 'pointerup', event => dispatch({type:'DRAG_END', pointerId:event.pointerId, x:event.clientX, y:event.clientY}));
    ctx.input.on(box, 'pointercancel', event => {
      if (drag.active && drag.pointerId === event.pointerId) dispatch({type:'CANCEL'});
    });
    ctx.input.on(box, 'lostpointercapture', event => {
      if (drag.active && drag.pointerId === event.pointerId) dispatch({type:'CANCEL'});
    });
    ctx.input.on(box, 'dragstart', event => event.preventDefault());
  }
  surface.append(header, stats, storage, el('h2', 'post-section', '01 / Заберите посылки'), rack, el('h2', 'post-section', '02 / Доставьте по цвету'), bins, message, el('p', 'post-help', 'Клавиатура: 1 / 2 / 3 — выбрать, R / G / B — отправить. Esc — отменить. Ошибки не штрафуются.'));
  ctx.root.append(surface);
  function hit(x, y) {
    return baskets.findIndex(node => {
      const r = node.getBoundingClientRect();
      return x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
    }) + 1;
  }
  function render() {
    if (disposed) return;
    count.textContent = 'Доставлено: ' + score + '/3';
    best.textContent = 'Рекорд: ' + bestScore + '/3';
    const statuses = {loading:'Проверяем сохранение', available:'Хранилище доступно', saving:'Сохраняем рекорд', saved:'Рекорд сохранен', unavailable:'Рекорд только в этой сессии', error:'Рекорд только в этой сессии'};
    storage.textContent = statuses[storageStatus] + (storageReason ? ': ' + storageReason : '');
    message.textContent = feedback;
    message.classList.toggle('post-victory', phase === 'won');
    const hovered = drag.active ? hit(drag.x, drag.y) : 0;
    parcels.forEach((parcel, i) => {
      const box = boxes[i];
      const parent = parcel.delivered ? contents[i] : slots[i];
      if (box.parentNode !== parent) parent.append(box);
      box.classList.toggle('post-selected', selectedParcelId === parcel.id);
      box.classList.toggle('post-delivered', parcel.delivered);
      box.classList.toggle('post-dragging', drag.active && drag.parcelId === parcel.id);
      box.setAttribute('aria-disabled', String(phase !== 'playing' || parcel.delivered));
      box.querySelector('.post-small').textContent = parcel.delivered ? '✓ ДОСТАВЛЕНО' : 'ПОСЫЛКА';
      baskets[i].classList.toggle('post-hover', hovered === parcel.id);
    });
    if (drag.active) {
      const box = boxes[drag.parcelId - 1];
      box.style.left = (drag.x - offsetX) + 'px';
      box.style.top = (drag.y - offsetY) + 'px';
    }
  }
  function clearDrag() {
    if (!drag.active) return;
    const old = drag;
    drag = emptyDrag();
    const box = boxes[old.parcelId - 1];
    box.style.cssText = '';
    box.classList.remove('post-dragging');
    try { if (box.hasPointerCapture(old.pointerId)) box.releasePointerCapture(old.pointerId); } catch (_) {}
  }
  async function writeBest() {
    if (!loaded || writing || disposed || !ctx.storage || storageStatus === 'error' || storageStatus === 'unavailable' || bestScore <= persisted) return;
    writing = true;
    try {
      while (!disposed && bestScore > persisted) {
        const value = bestScore;
        storageStatus = 'saving'; storageReason = ''; render();
        const result = await ctx.storage.save({bestScore:value});
        if (disposed) break;
        if (result !== true) throw new Error('запись не подтверждена');
        persisted = value;
      }
      if (!disposed) { storageStatus = 'saved'; render(); }
    } catch (_) {
      if (!disposed) { storageStatus = 'error'; storageReason = 'не удалось записать рекорд'; render(); }
    } finally { writing = false; }
  }
  async function loadBest() {
    if (!ctx.storage) return;
    try {
      const data = await ctx.storage.load();
      if (disposed) return;
      if (data === null || data === false) {
        storageStatus = 'unavailable'; storageReason = 'чтение недоступно';
      } else {
        if (data && Number.isInteger(data.bestScore) && data.bestScore >= 0 && data.bestScore <= 3 && Object.keys(data).length === 1) {
          persisted = data.bestScore;
          bestScore = Math.max(bestScore, persisted);
        }
        storageStatus = 'available';
      }
    } catch (_) {
      if (disposed) return;
      storageStatus = 'error'; storageReason = 'не удалось прочитать рекорд';
    }
    loaded = true; render();
    if (bestScore > 0) writeBest();
  }
  function deliver(id, target) {
    const parcel = parcels[id - 1];
    if (!parcel || parcel.delivered || phase !== 'playing') return;
    if (id !== target) { feedback = target ? 'Не та корзина! Попробуйте цвет посылки.' : 'Посылка вернулась. Отпустите её над корзиной.'; return; }
    parcel.delivered = true;
    score = parcels.filter(p => p.delivered).length;
    bestScore = Math.max(bestScore, score);
    selectedParcelId = 0;
    feedback = names[id - 1] + ' посылка доставлена!';
    if (score === 3) { phase = 'won'; feedback = 'Все 3 посылки доставлены! Отличная работа. Можно начать снова.'; }
    writeBest();
  }
  function dispatch(action) {
    if (disposed || !action || typeof action.type !== 'string') return;
    const type = action.type;
    if (type === 'RESTART') {
      clearDrag(); parcels.forEach(p => { p.delivered = false; }); score = 0; selectedParcelId = 0; phase = 'playing'; feedback = 'Новая смена! Доставьте три посылки.';
    } else if (type === 'START') {
      if (phase === 'ready') { phase = 'playing'; feedback = 'Почта открыта! Перетащите посылку в корзину.'; }
    } else if (phase === 'playing') {
      if (type === 'CANCEL') {
        clearDrag(); selectedParcelId = 0; feedback = 'Выбор отменён. Посылки на месте.';
      } else if (type === 'SELECT_PARCEL' && !drag.active) {
        const id = Number(action.parcelId);
        if (Number.isInteger(id) && id >= 1 && id <= 3 && !parcels[id - 1].delivered) {
          selectedParcelId = id; feedback = 'Выбрана ' + names[id - 1].toLowerCase() + ' посылка. Нажмите R, G или B.';
        }
      } else if (type === 'ASSIGN_BASKET' && !drag.active && selectedParcelId) {
        const target = typeof action.basket === 'string' ? letters.indexOf(action.basket.toUpperCase()) + 1 : Number(action.basketId);
        if (target >= 1 && target <= 3) deliver(selectedParcelId, target);
      } else if (type === 'DRAG_BEGIN' && !drag.active) {
        const id = Number(action.parcelId);
        if (Number.isInteger(id) && id >= 1 && id <= 3 && !parcels[id - 1].delivered && Number.isFinite(action.x) && Number.isFinite(action.y) && Number.isInteger(action.pointerId)) {
          const box = boxes[id - 1], r = box.getBoundingClientRect();
          offsetX = action.x - r.left; offsetY = action.y - r.top;
          selectedParcelId = 0;
          drag = {active:true, parcelId:id, pointerId:action.pointerId, startX:action.x, startY:action.y, x:action.x, y:action.y, moved:false};
          box.style.width = r.width + 'px'; box.style.height = r.height + 'px';
          try { box.setPointerCapture(action.pointerId); } catch (_) {}
        }
      } else if ((type === 'DRAG_MOVE' || type === 'DRAG_END') && drag.active && action.pointerId === drag.pointerId && Number.isFinite(action.x) && Number.isFinite(action.y)) {
        drag.x = action.x; drag.y = action.y;
        drag.moved = drag.moved || Math.hypot(drag.x - drag.startX, drag.y - drag.startY) >= 8;
        if (type === 'DRAG_END') {
          const id = drag.parcelId, moved = drag.moved, target = hit(drag.x, drag.y);
          clearDrag();
          if (moved) deliver(id, target);
          else feedback = 'Нужно перетащить посылку, а не просто нажать.';
        }
      }
    }
    render();
  }
  ctx.input.key((key, event) => {
    const upper = key.toUpperCase();
    if (/^[123]$/.test(key)) { event.preventDefault(); dispatch({type:'SELECT_PARCEL', parcelId:Number(key)}); }
    else if (letters.includes(upper)) { event.preventDefault(); dispatch({type:'ASSIGN_BASKET', basket:upper}); }
    else if (key === 'Escape') { event.preventDefault(); dispatch({type:'CANCEL'}); }
  });
  ctx.input.on(surface, 'focusout', event => {
    if (!surface.contains(event.relatedTarget)) dispatch({type:'CANCEL'});
  });
  function dispose() { if (disposed) return; clearDrag(); disposed = true; surface.remove(); }
  ctx.cleanup(dispose);
  render(); loadBest();
  return {
    snapshot() { return {phase, score, bestScore, storageStatus, parcels:parcels.map(p => ({...p})), selectedParcelId, drag:{...drag}, feedback}; },
    dispatch,
    pause(hidden) { if (hidden) dispatch({type:'CANCEL'}); },
    dispose
  };
}

function createGame(ctx) {
  const root = ctx.root;
  const colors = ['red', 'green', 'blue'];
  const names = ['Красная', 'Зеленая', 'Синяя'];
  const keys = ['R', 'G', 'B'];
  let phase = 'ready', score = 0, bestScore = 0, selectedParcelId = 0;
  let feedback = 'Нажмите «Начать», чтобы сортировать посылки.';
  let disposed = false;
  const storage = ctx.storage;
  let storageStatus = storage ? 'loading' : 'unavailable';
  let persisted = -1, writing = false, loaded = !storage;
  const parcels = colors.map((color, i) => ({ id: i + 1, color, delivered: false }));
  const emptyDrag = () => ({ active: false, parcelId: 0, pointerId: 0, startX: 0, startY: 0, x: 0, y: 0, moved: false });
  let drag = emptyDrag();
  root.innerHTML = '<section class="sorting-game"><header><span class="eyebrow">ПОЧТОВАЯ СТАНЦИЯ · 01</span><h1>Сортировщик посылок</h1><div class="scoreline"><strong class="score"></strong><span class="best"></span></div><p class="storage-note"></p></header><p class="rules">Перетащите каждую посылку в корзину того же цвета.<br><b>Клавиатура:</b> 1 / 2 / 3 — выбор, R / G / B — доставка, Esc — отмена.</p><div class="station"><h2>Посылки <span>возьмите и перенесите ↓</span></h2><div class="homes"></div><div class="route" aria-hidden="true">↓<span>Сопоставьте номер и цвет</span>↓</div><h2>Корзины</h2><div class="baskets"></div></div><p class="feedback" role="status" aria-live="polite" aria-atomic="true"></p></section>';
  root.tabIndex = 0;
  const find = s => root.querySelector(s);
  const homes = [], baskets = [], nodes = [];
  for (let i = 0; i < 3; i++) {
    const home = document.createElement('div');
    home.className = 'parcel-home';
    const hint = document.createElement('span');
    hint.className = 'home-number';
    hint.textContent = String(i + 1);
    home.appendChild(hint);
    const node = document.createElement('div');
    node.className = 'parcel ' + colors[i];
    node.dataset.testid = 'parcel-' + (i + 1);
    node.setAttribute('aria-label', names[i] + ' посылка ' + (i + 1));
    node.innerHTML = '<span class="parcel-number">' + (i + 1) + '</span><span>' + names[i] + '</span><span class="delivered-mark" aria-hidden="true">✓</span>';
    node.draggable = false;
    home.appendChild(node);
    find('.homes').appendChild(home);
    const basket = document.createElement('div');
    basket.className = 'basket ' + colors[i];
    basket.dataset.testid = 'basket-' + (i + 1);
    basket.innerHTML = '<div class="basket-label">' + (i + 1) + ' · ' + names[i] + '<br><kbd>' + keys[i] + '</kbd></div><div class="basket-slot"></div>';
    find('.baskets').appendChild(basket);
    homes.push(home); baskets.push(basket); nodes.push(node);
    ctx.input.on(node, 'pointerdown', event => {
      if (event.button !== 0 || event.isPrimary === false || drag.active || phase !== 'playing' || parcels[i].delivered) return;
      event.preventDefault();
      root.focus({ preventScroll: true });
      dispatch({ type: 'BEGIN_DRAG', parcelId: i + 1, pointerId: event.pointerId, x: event.clientX, y: event.clientY });
      if (drag.active && drag.pointerId === event.pointerId) {
        try { node.setPointerCapture(event.pointerId); } catch (_) { dispatch({ type: 'CANCEL' }); }
      }
    });
    ctx.input.on(node, 'pointermove', event => dispatch({ type: 'MOVE_DRAG', pointerId: event.pointerId, x: event.clientX, y: event.clientY }));
    ctx.input.on(node, 'pointerup', event => dispatch({ type: 'END_DRAG', pointerId: event.pointerId, x: event.clientX, y: event.clientY }));
    for (const type of ['pointercancel', 'lostpointercapture']) {
      ctx.input.on(node, type, event => {
        if (drag.active && drag.pointerId === event.pointerId) dispatch({ type: 'CANCEL' });
      });
    }
    ctx.input.on(node, 'dragstart', event => event.preventDefault());
  }
  function render() {
    if (disposed) return;
    find('.score').textContent = score + ' / 3 доставлено';
    find('.best').textContent = 'Лучший счет: ' + bestScore;
    const messages = {
      loading: 'Загрузка лучшего счета…', available: 'Хранилище готово', saving: 'Сохранение лучшего счета…',
      saved: 'Лучший счет сохранен', unavailable: 'Лучший счет — только в этом сеансе',
      error: 'Не удалось сохранить: результат доступен в этом сеансе'
    };
    find('.storage-note').textContent = messages[storageStatus];
    find('.feedback').textContent = feedback;
    for (let i = 0; i < 3; i++) {
      const node = nodes[i];
      const parent = parcels[i].delivered ? baskets[i].querySelector('.basket-slot') : homes[i];
      if (node.parentNode !== parent) parent.appendChild(node);
      node.classList.toggle('selected', selectedParcelId === i + 1);
      node.classList.toggle('delivered', parcels[i].delivered);
      const dragging = drag.active && drag.parcelId === i + 1;
      node.classList.toggle('dragging', dragging);
      node.style.transform = dragging ? 'translate(' + (drag.x - drag.startX) + 'px,' + (drag.y - drag.startY) + 'px)' : '';
      baskets[i].classList.toggle('filled', parcels[i].delivered);
    }
  }
  function clearDrag() {
    const old = drag;
    drag = emptyDrag();
    if (old.active) {
      const node = nodes[old.parcelId - 1];
      node.style.transform = '';
      try { if (node.hasPointerCapture(old.pointerId)) node.releasePointerCapture(old.pointerId); } catch (_) {}
    }
  }
  async function saveBest() {
    if (!storage || !loaded || writing || disposed || bestScore <= persisted) return;
    writing = true;
    try {
      while (!disposed && bestScore > persisted) {
        const value = bestScore;
        storageStatus = 'saving'; render();
        const result = await storage.save({ bestScore: value });
        if (disposed) return;
        if (result === false || result === null) throw new Error('save failed');
        persisted = value;
        storageStatus = 'saved'; render();
      }
    } catch (_) {
      if (!disposed) { storageStatus = 'error'; render(); }
    } finally { writing = false; }
  }
  function deliver(parcelId, basketId) {
    const parcel = parcels[parcelId - 1];
    if (!parcel || parcel.delivered) return;
    if (parcelId !== basketId) {
      feedback = 'Не та корзина. Найдите совпадающий номер и цвет.';
      return;
    }
    parcel.delivered = true;
    score = parcels.filter(p => p.delivered).length;
    bestScore = Math.max(bestScore, score);
    selectedParcelId = 0;
    feedback = 'Посылка ' + parcelId + ' доставлена!';
    if (score === 3) { phase = 'won'; feedback = 'Все посылки доставлены!'; }
    void saveBest();
  }
  function dispatch(action) {
    if (disposed || !action || typeof action.type !== 'string') return;
    if (action.type === 'RESTART' || (action.type === 'START' && phase === 'ready')) {
      clearDrag(); selectedParcelId = 0;
      parcels.forEach(p => { p.delivered = false; });
      score = 0; phase = 'playing'; feedback = 'Перенесите посылки в корзины. Можно начать с любой.';
      render(); return;
    }
    if (phase !== 'playing') return;
    const validPoint = Number.isFinite(action.x) && Number.isFinite(action.y);
    const id = action.parcelId;
    const available = Number.isInteger(id) && id >= 1 && id <= 3 && !parcels[id - 1].delivered;
    switch (action.type) {
      case 'SELECT_PARCEL':
        if (!drag.active && available) { selectedParcelId = id; feedback = 'Выбрана посылка ' + id + '. Нажмите R, G или B.'; }
        break;
      case 'BEGIN_DRAG':
        if (drag.active || !available || !validPoint || !Number.isInteger(action.pointerId)) return;
        selectedParcelId = id;
        drag = { active: true, parcelId: id, pointerId: action.pointerId, startX: action.x, startY: action.y, x: action.x, y: action.y, moved: false };
        feedback = 'Отпустите посылку в подходящей корзине.';
        break;
      case 'MOVE_DRAG':
        if (!drag.active || drag.pointerId !== action.pointerId || !validPoint) return;
        drag.x = action.x; drag.y = action.y;
        drag.moved = drag.moved || Math.hypot(drag.x - drag.startX, drag.y - drag.startY) >= 6;
        break;
      case 'END_DRAG': {
        if (!drag.active || drag.pointerId !== action.pointerId) return;
        const old = { ...drag };
        clearDrag();
        if (validPoint && old.moved) {
          let target = 0;
          baskets.forEach((basket, index) => {
            const r = basket.getBoundingClientRect();
            if (action.x >= r.left && action.x <= r.right && action.y >= r.top && action.y <= r.bottom) target = index + 1;
          });
          selectedParcelId = 0;
          deliver(old.parcelId, target);
        } else { feedback = 'Для доставки перетащите посылку или используйте клавиатуру.'; }
        break;
      }
      case 'KEYBOARD_DELIVER':
        if (!drag.active && selectedParcelId && Number.isInteger(action.basketId) && action.basketId >= 1 && action.basketId <= 3) deliver(selectedParcelId, action.basketId);
        break;
      case 'CANCEL':
        clearDrag(); selectedParcelId = 0; feedback = 'Отменено. Посылка остается на месте.';
        break;
      default: return;
    }
    render();
  }
  ctx.input.key((key, event) => {
    const k = String(key).toLowerCase();
    if (event && event.repeat) return;
    if (!['1', '2', '3', 'r', 'g', 'b', 'escape'].includes(k)) return;
    if (event) event.preventDefault();
    if (k === 'escape') dispatch({ type: 'CANCEL' });
    else if ('123'.includes(k)) dispatch({ type: 'SELECT_PARCEL', parcelId: Number(k) });
    else dispatch({ type: 'KEYBOARD_DELIVER', basketId: ['r', 'g', 'b'].indexOf(k) + 1 });
  });
  ctx.input.on(root, 'focusout', event => {
    if (!event.relatedTarget || !root.contains(event.relatedTarget)) dispatch({ type: 'CANCEL' });
  });
  ctx.resize(() => { if (drag.active) dispatch({ type: 'CANCEL' }); });
  render();
  if (storage) {
    (async () => {
      try {
        const data = await storage.load();
        if (disposed) return;
        if (data && typeof data === 'object' && !Array.isArray(data) && Object.keys(data).length === 1 && Number.isInteger(data.bestScore) && data.bestScore >= 0 && data.bestScore <= 3) {
          persisted = data.bestScore; bestScore = Math.max(bestScore, persisted);
        }
        storageStatus = 'available';
      } catch (_) { if (!disposed) storageStatus = 'error'; }
      if (disposed) return;
      loaded = true; render();
      if (bestScore > 0 && bestScore > persisted) void saveBest();
    })();
  }
  function dispose() { clearDrag(); disposed = true; }
  ctx.cleanup(dispose);
  return {
    snapshot() { return { phase, score, bestScore, selectedParcelId, parcels: parcels.map(p => ({ ...p })), drag: { ...drag }, storageStatus, feedback }; },
    dispatch,
    pause(hidden) { if (hidden) dispatch({ type: 'CANCEL' }); },
    dispose
  };
}

reviewed_source.style.css:
.sorting-game { box-sizing: border-box; max-width: 720px; margin: 0 auto; padding: 22px 16px; color: #233047; background: #f6f8fc; font: 15px/1.45 system-ui, sans-serif; border-radius: 20px; }
.sorting-game * { box-sizing: border-box; }
.sorting-game .eyebrow { color: #596b82; font-size: 11px; font-weight: 800; letter-spacing: .14em; }
.sorting-game h1 { font-size: clamp(23px, 5vw, 32px); line-height: 1.15; margin: 8px 0 18px; }
.sorting-game .scoreline { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 22px; }
.sorting-game .score { font-size: 23px; }
.sorting-game .best { font-weight: 650; }
.sorting-game .storage-note { color: #53627a; font-size: 12px; min-height: 18px; margin: 5px 0 16px; }
.sorting-game .rules { margin: 0 0 20px; font-size: 13px; }
.sorting-game .station { padding: 14px 10px; background: white; border: 1px solid #d9e1ed; border-radius: 15px; }
.sorting-game h2 { font-size: 13px; margin: 0 0 12px; }
.sorting-game h2 span { color: #637188; font-size: 11px; font-weight: 400; margin-left: 8px; }
.sorting-game .homes, .sorting-game .baskets { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.sorting-game .parcel-home { height: 90px; position: relative; display: flex; align-items: center; justify-content: center; border: 1px dashed #ccd4e1; border-radius: 10px; background: #f7f9fc; }
.sorting-game .home-number { position: absolute; color: #bcc7d8; font-size: 28px; }
.sorting-game .red { --ink: #9c2935; --tint: #ffe1dd; --line: #cb5360; }
.sorting-game .green { --ink: #1d684e; --tint: #d9f2e4; --line: #398565; }
.sorting-game .blue { --ink: #24569d; --tint: #dceaff; --line: #507fbc; }
.sorting-game .parcel { position: relative; flex-shrink: 0; width: 86px; max-width: 100%; height: 76px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: var(--tint); border: 2px solid var(--line); border-radius: 8px; color: var(--ink); font-size: 12px; font-weight: 750; cursor: grab; user-select: none; -webkit-user-select: none; touch-action: none; box-shadow: 0 3px 0 #23304716; }
.sorting-game .parcel::before { content: ''; position: absolute; top: 0; height: 10px; width: 18px; background: #ffffff90; border-left: 1px solid var(--line); border-right: 1px solid var(--line); }
.sorting-game .parcel-number { font-size: 25px; line-height: 1.3; }
.sorting-game .parcel.selected { outline: 3px solid #243650; outline-offset: 3px; }
.sorting-game .parcel.dragging { z-index: 10; cursor: grabbing; box-shadow: 0 12px 24px #20304940; }
.sorting-game .route { display: flex; justify-content: space-around; align-items: center; height: 90px; color: #91a0b7; font-size: 25px; }
.sorting-game .route span { font-size: 11px; color: #66758c; }
.sorting-game .basket { min-height: 144px; border: 2px solid var(--line); border-top: 5px solid var(--line); border-radius: 5px 5px 14px 14px; background: var(--tint); color: var(--ink); padding: 8px 3px; }
.sorting-game .basket-label { text-align: center; font-size: 12px; font-weight: 750; white-space: nowrap; }
.sorting-game kbd { display: inline-block; margin-top: 3px; min-width: 22px; background: #ffffffa8; border: 1px solid currentColor; border-radius: 4px; font: bold 12px system-ui, sans-serif; }
.sorting-game .basket-slot { display: flex; align-items: center; justify-content: center; min-height: 80px; margin-top: 5px; }
.sorting-game .parcel.delivered { cursor: default; width: 76px; height: 70px; background: #fff; }
.sorting-game .delivered-mark { display: none; position: absolute; right: 4px; top: 2px; font-size: 17px; }
.sorting-game .delivered .delivered-mark { display: block; }
.sorting-game .feedback { margin: 16px 0 0; min-height: 48px; padding: 12px; border-radius: 10px; background: #e8eef8; color: #263d60; font-weight: 650; font-size: 14px; }
@media (max-width: 380px) { .sorting-game { padding: 16px 10px; } .sorting-game .station { padding: 12px 6px; } .sorting-game .homes, .sorting-game .baskets { gap: 8px; } .sorting-game .parcel { font-size: 11px; } .sorting-game .basket-label { font-size: 10px; } }
